{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "In healthy men, 11C-SCH 23390, the closest direct analogue with the same chloro-phenol benzazepine core, showed rapid transfer into brain with 1.2% of injected radioactivity at 4.5 min, demonstrating meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The iodinated benzazepine analogue [125I]FISCH showed good rat brain uptake after intravenous injection (2.27% dose/whole brain at 2 min), supporting CNS penetration for halogenated 3-benzazepines closely related to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "The iodo-substituted benzazepine analogue S-(-)-8 had good initial brain uptake in rats (1.59% dose/organ at 2 min), indicating that this structural family crosses the blood-brain barrier with ease.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A more distant but related catechol-containing CNS agent, S(+)-apomorphine, achieved a brain AUC of 228% relative to plasma in mice, confirming that this general scaffold can produce high CNS exposure after systemic dosing.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Direct in vivo PET and biodistribution data for close SCH23390-type benzazepine analogues consistently show rapid, meaningful brain uptake after systemic administration. The query's added lipophilic dichlorodihydrobenzofuran and halogenation are unlikely to abolish CNS access, and the transferable experimental evidence overrides the uncertain physicochemical prior.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule.",
    "Efflux-transporter phenotype of the query is not experimentally defined.",
    "Quantitative unbound brain-to-plasma ratio for the query is not available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

